INSERT INTO warscape_enemy_family VALUES (24,'warriors','Warriors','Human infantry with tier weapons: Scarlet warrior 2471/2482, guards 3167/5446; melee Barbarians, Warriors and Al Kharid warrior.');
INSERT INTO warscape_enemy_family VALUES (25,'knights','Knights','Human plate guard displays: Dalaran male/Scarlet female for Black Knights, Stormwind guard male/female for White Knights; stock colours are approximations.');
INSERT INTO warscape_enemy_family VALUES (26,'hobgoblins','Hobgoblins','Roughly dressed Peon orc display 10038, scaled; spear on armed source forms.');
INSERT INTO warscape_enemy_family VALUES (27,'flesh_crawlers','Flesh Crawlers','Silithid Grub display 7572, varied scale.');
INSERT INTO warscape_enemy_family VALUES (28,'ogres','Ogres','Classic Boulderfist Ogre/Mauler displays 1052/1051.');
INSERT INTO warscape_enemy_family VALUES (29,'bandits','Bandits','Defias Bandit/Highwayman displays 2357/2342, sword/dagger and leather.');
INSERT INTO warscape_enemy_family VALUES (30,'rogues','Rogues','Defias Cutpurse display 2361 with two daggers; regular melee level 15 only.');
